INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('ptfe_teflon', 'Polytetrafluoroethylene (PTFE / Teflon)', 'fluoropolymer', 'solid', '(C2F4)n', ARRAY['Teflon', 'Teflon®', 'PTFE', 'polytetrafluoroethylene']::text[], 'Wire insulation, tubing, seals, thermal blankets and other polymer components in crewed habitats.', 'Melts and can drip; thermal decomposition can release HF and carbonyl fluoride. SAME data show very small smoke particles that are hard for optical detectors to see.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('polyimide_kapton', 'Polyimide (Kapton)', 'polyimide', 'solid', '(C22H10N2O5)n', ARRAY['Kapton', 'Kapton®', 'polyimide', 'PI']::text[], 'Wire and cable insulation, flexible circuits, thermal blankets and heater films.', 'Chars rather than melts; can smolder and produce ultrafine smoke. Relevant to detection and to arc-track / insulation failure scenarios.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('silicone_rubber', 'Silicone rubber', 'elastomer', 'solid', '[-Si(CH3)2O-]n', ARRAY['silicone', 'silicone rubber', 'RTV silicone', 'siloxane']::text[], 'Seals, gaskets, potting compounds, flexible insulation and crew equipment.', 'Leaves silica ash; can smolder. SAME data show a larger smoke-particle mode than Teflon or Kapton.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('pyrell_foam', 'Pyrell intumescent foam', 'foam', 'solid', NULL, ARRAY['Pyrell', 'Pyrell®', 'Pyrel', 'intumescent polyurethane foam']::text[], 'Fire-retardant foam used as a test material for smoke generation and material flammability.', 'Intumescent fire-retardant foam by Foamex. SAME-R introduced Pyrell to replace the liquid DBP smoke source and to test a realistic solid foam.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('cotton_lampwick', 'Cotton lamp wick (cellulose)', 'cellulose', 'solid', '(C6H10O5)n', ARRAY['lampwick', 'lamp wick', 'cotton lamp wick', 'cotton wick', 'cellulose']::text[], 'Cellulosic representative fuel; wick material used to hold liquid smoke sources.', 'Pyrolysis, charring and smoldering; a standard cellulosic solid fuel in SAME and SAME-R.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('sibal_fabric', 'SIBAL cotton-fiberglass fabric', 'composite_fabric', 'solid', NULL, ARRAY['SIBAL', 'Sibal', 'cotton-fiberglass fabric', 'cotton fiberglass fabric', 'SIBAL cloth']::text[], 'NASA solid-fuel flammability test material; analog for clothing, linens and other cellulosic fabrics in spacecraft.', '75% cotton + 25% fiberglass by mass. Burns like cotton but keeps structural integrity after the cotton is consumed, which makes it useful for long-duration flame-spread tests.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('cotton', 'Cotton (cellulose)', 'cellulose', 'solid', '(C6H10O5)n', ARRAY['cotton', 'cellulose']::text[], 'Constituent of SIBAL and a common clothing/bedding material.', 'Cellulosic fuel; burns and chars. The combustible part of SIBAL.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('fiberglass', 'Fiberglass (glass fiber)', 'inorganic_fiber', 'solid', 'SiO2-based glass', ARRAY['fiberglass', 'fibre glass', 'glass fiber', 'glass fibre', 'E-glass']::text[], 'Composite reinforcement and fire-resistant structural fabric.', 'Noncombustible inorganic reinforcement. Retains the sample shape after the cotton burns, affecting flame spread and extinction.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('nomex_aramid', 'Nomex aramid fabric', 'aramid', 'solid', '(C14H12O2N2)n', ARRAY['Nomex', 'Nomex®', 'meta-aramid', 'aramid', 'Nomex III']::text[], 'Fire-resistant clothing, insulation, stowage and cabin fabrics.', 'Char-forming aramid. BASS showed that some Nomex variants can burn in high-oxygen, low-velocity microgravity conditions, while others self-extinguish.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('ultem_pei', 'Ultem polyetherimide (PEI)', 'polyetherimide', 'solid', '(C37H24O6N2)n', ARRAY['Ultem', 'Ultem®', 'PEI', 'polyetherimide']::text[], 'High-performance aerospace plastic used for connectors, brackets and structural parts.', 'BASS tested Ultem rods; the material did not sustain burning in ISS atmosphere in those tests.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('pmma_acrylic', 'Polymethyl methacrylate (PMMA / acrylic)', 'acrylic', 'solid', '(C5H8O2)n', ARRAY['PMMA', 'polymethyl methacrylate', 'polymethylmethacrylate', 'acrylic', 'Plexiglas', 'Lucite']::text[], 'Transparent structural plastic; idealized solid fuel for flame-spread experiments.', 'Clean-burning thermoplastic and a standard benchmark for opposed and concurrent flame spread. BASS used rods, slabs and spheres; SAFFIRE-II used flat PMMA.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('paraffin_wax', 'Paraffin wax', 'wax', 'solid', 'CnH2n+2 (C20-C40)', ARRAY['paraffin', 'paraffin wax', 'wax']::text[], 'Phase-change material, candle analog and solid fuel.', 'Melts and burns as a pool. BASS used fiberglass fabric saturated with paraffin wax.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('japan_wax', 'Japan wax (candle wax)', 'wax', 'solid', 'triglyceride mixture', ARRAY['Japan wax', 'candle wax', 'candle']::text[], 'Candle analog for microgravity flame studies.', 'BASS burned Japan-wax candles inside tubes to study low-velocity candle flames.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('dbp', 'Dibutyl phthalate (DBP)', 'phthalate', 'liquid', 'C16H22O4', ARRAY['DBP', 'dibutyl phthalate', 'dibutyl-phthalate']::text[], 'Liquid smoke source used to generate controlled pyrolysis aerosol in SAME.', 'Deposited on a cotton wick and heated. Replaced by Pyrell in SAME-R because a solid fire-retardant foam was more representative.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_heptane', 'n-Heptane', 'alkane', 'liquid', 'C7H16', ARRAY['heptane', 'n-heptane', 'C7H16']::text[], 'Reference liquid fuel and diesel/Jet-A surrogate.', 'Well-characterized droplet fuel; FLEX measured LOI and suppression effectiveness, FLEX-2 used heptane in surrogate mixtures.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_dodecane', 'n-Dodecane', 'alkane', 'liquid', 'C12H26', ARRAY['dodecane', 'n-dodecane', 'C12H26']::text[], 'Diesel and Jet-A surrogate; cool-flame droplet fuel.', 'CFI burned n-dodecane droplets and n-dodecane/iso-dodecane blends at 0.25-5 atm.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('iso_dodecane', 'iso-Dodecane', 'branched_alkane', 'liquid', 'C12H26', ARRAY['isododecane', 'iso-dodecane', '2,2,4,6,6-pentamethylheptane']::text[], 'Branched surrogate component in aviation/diesel fuel blends.', 'CFI tested 60/40 and 75/25 n-dodecane/iso-dodecane blends to study cool-flame behavior.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('farnesane', 'Farnesane', 'branched_alkane', 'liquid', 'C15H32', ARRAY['farnesane', '2,6,10-trimethyldodecane']::text[], 'Sustainable aviation fuel surrogate.', 'Branched C15 alkane burned as a droplet in CFI to extend cool-flame data to larger molecules.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_decane', 'n-Decane', 'alkane', 'liquid', 'C10H22', ARRAY['decane', 'n-decane', 'C10H22']::text[], 'Diesel/Jet-A surrogate and FLEX-2 droplet fuel.', 'FLEX-2 focused on ethanol and decane as fuels and on decane/propylbenzene surrogate mixtures.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_octane', 'n-Octane', 'alkane', 'liquid', 'C8H18', ARRAY['octane', 'n-octane', 'C8H18']::text[], 'Gasoline surrogate component.', 'FLEX-2 surrogate-fuel test matrix included 100% n-octane and iso-octane.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('iso_octane', 'iso-Octane', 'branched_alkane', 'liquid', 'C8H18', ARRAY['isooctane', 'iso-octane', '2,2,4-trimethylpentane']::text[], 'Gasoline surrogate component.', 'FLEX-2 surrogate-fuel test matrix.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('toluene', 'Toluene', 'aromatic', 'liquid', 'C7H8', ARRAY['toluene', 'methylbenzene', 'C7H8']::text[], 'Aromatic surrogate component; soot precursor.', 'FLEX-2 surrogate-fuel test matrix; aromatic fuels strongly affect soot production.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('propylbenzene', 'n-Propylbenzene', 'aromatic', 'liquid', 'C9H12', ARRAY['propylbenzene', 'n-propylbenzene', 'C9H12']::text[], 'Aromatic surrogate component; soot precursor.', 'FLEX-2 used propylbenzene and decane/propylbenzene mixtures.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_propanol', '1-Propanol', 'alcohol', 'liquid', 'C3H8O', ARRAY['propanol', '1-propanol', 'n-propanol', 'C3H8O']::text[], 'Oxygenated fuel component.', 'FLEX-2 condensed-phase test matrix used propanol/glycerol mixtures.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('glycerol', 'Glycerol', 'polyol', 'liquid', 'C3H8O3', ARRAY['glycerol', 'glycerin', 'C3H8O3']::text[], 'Condensed-phase fuel additive; biofuel byproduct.', 'FLEX-2 used 95% propanol / 5% glycerol and 80/20 mixtures to study condensed-phase droplet burning.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('ethanol', 'Ethanol', 'alcohol', 'liquid', 'C2H6O', ARRAY['ethanol', 'ethyl alcohol', 'C2H6O']::text[], 'Biofuel constituent and oxygenated fuel.', 'FLEX-2 focused on ethanol and decane; ethanol/decane binary droplets were used to study differential vaporization.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('methanol', 'Methanol', 'alcohol', 'liquid', 'CH4O', ARRAY['methanol', 'methyl alcohol', 'MeOH', 'CH3OH']::text[], 'Oxygenated fuel and cool-flame reference fuel.', 'FLEX measured LOI and suppressant effectiveness for heptane and methanol; PSI-117 modeled methanol cool flames.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_hexadecane', 'n-Hexadecane', 'alkane', 'liquid', 'C16H34', ARRAY['hexadecane', 'n-hexadecane', 'cetane', 'C16H34']::text[], 'Bi-component droplet fuel; diesel surrogate.', 'FLEX-2 references heptane-hexadecane mixture droplets for differential vaporization studies.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('methane', 'Methane', 'gas_fuel', 'gas', 'CH4', ARRAY['methane', 'CH4', 'natural gas']::text[], 'Gaseous fuel; relevant to cabin atmosphere contamination and life-support processes.', 'Simple gaseous fuel used in ACME CLD, s-Flame, E-FIELD, SLICE, SPICE and BRE. Cleaner soot behavior than ethylene.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('ethylene', 'Ethylene', 'gas_fuel', 'gas', 'C2H4', ARRAY['ethylene', 'ethene', 'C2H4']::text[], 'Gaseous fuel and soot precursor; common in combustion research.', 'Strongly sooting gaseous fuel used in ACME Flame Design, CLD, s-Flame, E-FIELD, SLICE, SPICE, BRE and PSI-10.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('ethane', 'Ethane', 'gas_fuel', 'gas', 'C2H6', ARRAY['ethane', 'C2H6']::text[], 'Gaseous fuel; CFI-G alternative fuel.', 'Substituted for n-pentane in CFI-G because n-pentane''s vapor pressure was too low.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('propane', 'Propane', 'gas_fuel', 'gas', 'C3H8', ARRAY['propane', 'C3H8', 'LPG']::text[], 'Gaseous fuel; smoke-point and flame-design studies.', 'SPICE found an unusually high sooting propensity for propane in microgravity. CFI-G burned propane cool flames.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_butane', 'n-Butane', 'gas_fuel', 'gas', 'C4H10', ARRAY['butane', 'n-butane', 'C4H10']::text[], 'Gaseous fuel; CFI-G.', 'CFI-G burned normal and inverse n-butane cool diffusion flames.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_pentane', 'n-Pentane', 'gas_fuel', 'liquid/gas', 'C5H12', ARRAY['pentane', 'n-pentane', 'C5H12']::text[], 'Planned CFI-G fuel.', 'Planned for CFI-G but replaced by ethane because its vapor pressure was too low for the ACME hardware.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('propylene', 'Propylene', 'gas_fuel', 'gas', 'C3H6', ARRAY['propylene', 'propene', 'C3H6']::text[], 'Gaseous fuel and soot precursor.', 'SPICE measured smoke points for propylene and propylene/nitrogen mixtures; it is the most strongly sooting fuel in that set.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('dimethyl_ether', 'Dimethyl ether (DME)', 'oxygenated_fuel', 'gas/liquid', 'C2H6O', ARRAY['dimethyl ether', 'DME', 'methoxymethane', 'C2H6O']::text[], 'Oxygenated fuel used in cool-flame ground experiments.', 'PSI-142 used DME/air mixtures for 1-D cool-flame and warm-flame modeling.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('n_tetradecane', 'n-Tetradecane', 'alkane', 'liquid', 'C14H30', ARRAY['tetradecane', 'n-tetradecane', 'C14H30']::text[], 'Large n-alkane cool-flame reference fuel.', 'PSI-142 compiled nC7, nC8, nC10, nC12 and nC14 cool-flame extinction data.', true);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('ozone', 'Ozone', 'oxidizer_additive', 'gas', 'O3', ARRAY['ozone', 'O3']::text[], 'Laboratory sensitizer for cool-flame experiments.', 'PSI-142 used ozone-sensitized counterflow flames to access cool-flame regimes at ground conditions.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('arizona_road_dust', 'Arizona Road Dust (fine)', 'aerosol_standard', 'solid', NULL, ARRAY['Arizona Road Dust', 'ARD', 'ARD Fine']::text[], 'Standardized aerosol for instrument validation, not a spacecraft material.', 'DAFT used ARD to validate the modified P-Trak and DustTrak aerosol monitors in microgravity. It is a test aerosol, not a combustion fuel.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('soot', 'Soot', 'combustion_product', 'solid', 'C (black carbon)', ARRAY['soot', 'black carbon', 'carbonaceous particulate']::text[], 'Fire signature, radiant heat source and detector challenge.', 'Soot volume fraction and radiation are central to flame spread and smoke detection.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('smoke_aerosol', 'Smoke aerosol', 'combustion_product', 'solid/gas', NULL, ARRAY['smoke', 'aerosol', 'particulate', 'particle size distribution']::text[], 'Fire detection and crew warning.', 'SAME and SAME-R measured smoke particle size distributions for different materials; detector response depends strongly on particle size.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('nitrogen', 'Nitrogen', 'atmosphere', 'gas', 'N2', ARRAY['nitrogen', 'N2', 'GN2']::text[], 'Cabin diluent and test-atmosphere balance gas.', 'Diluent; lowering oxygen mole fraction by adding nitrogen is a standard suppression/flammability-limit variable.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('carbon_dioxide', 'Carbon dioxide', 'suppressant', 'gas', 'CO2', ARRAY['carbon dioxide', 'CO2']::text[], 'Fire suppressant and metabolic product.', 'FLEX measured CO2 suppression effectiveness for heptane and methanol flames.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('helium', 'Helium', 'suppressant', 'gas', 'He', ARRAY['helium', 'He']::text[], 'Inert suppressant/diluent.', 'FLEX tested helium as a fire suppressant; its high diffusivity changes flame behavior.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('sulfur_hexafluoride', 'Sulfur hexafluoride', 'suppressant', 'gas', 'SF6', ARRAY['sulfur hexafluoride', 'SF6', 'sulphur hexafluoride']::text[], 'High-performance gaseous fire suppressant.', 'FLEX tested SF6 as a suppressant for heptane and methanol flames.', false);
INSERT INTO materials (id, canonical_name, category, phase, chemical_formula, aliases, spacecraft_relevance, fire_safety_notes, is_fuel) VALUES ('oxygen', 'Oxygen', 'oxidizer', 'gas', 'O2', ARRAY['oxygen', 'O2']::text[], 'Cabin oxidizer; oxygen concentration is a primary flammability variable.', 'Lowering oxygen mole fraction is the main lever for material flammability limits; many PSI tests vary O2 from ~15% to ~40%.', false);
